import { expect, type Page, test } from "@playwright/test";

import * as ui from "@e2e/ui-actions";

const MEMORY_NOTE = "e2e trace note";
const MEMORY_NOTE_PROMPT = "give me a short note";
const TRACE_MODE_BUTTON = "Memory";
const SUMMARY_SNIPPET = "Inspector memory and buttons trace captured";

type TriggerMemoryAndButtonsOptions = {
  waitForSummary?: boolean;
};

export const triggerMemoryAndButtonsFlow = async (
  page: Page,
  options: TriggerMemoryAndButtonsOptions = {},
) => {
  await test.step("Send inspector memory and buttons trigger", async () => {
    await ui.inspectorShell.actions(page).sendMessage("inspector test memory and buttons");
    await ui.conversationLog
      .assertions(page)
      .conversationEventReached("Flow inspector_memory_and_buttons started");
  });

  await test.step("Wait for memory note collect prompt", async () => {
    const locators = ui.conversationLog.getLocators(page);
    await expect(
      locators.botMessages.filter({ hasText: MEMORY_NOTE_PROMPT }),
      "Memory note collect prompt should appear before sending the note",
    ).toBeVisible();
  });

  await test.step("Provide memory note collect value", async () => {
    const botCountBefore = await ui.conversationLog.getLocators(page).botMessages.count();
    await ui.inspectorShell.actions(page).sendMessage(MEMORY_NOTE);
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(botCountBefore + 1);
  });

  await test.step("Select trace mode via quick-reply button", async () => {
    const memoryButton = ui.conversationLog.getLocators(page).botButton(TRACE_MODE_BUTTON);
    await expect(
      memoryButton,
      `Trace mode button "${TRACE_MODE_BUTTON}" should appear after the note is collected`,
    ).toBeVisible();
    await memoryButton.click();
    await ui.conversationLog
      .assertions(page)
      .conversationEventReached("Slot inspector_trace_mode set");
    if (options.waitForSummary) {
      await expect(
        ui.conversationLog.getLocators(page).botMessages.filter({ hasText: SUMMARY_SNIPPET }),
        "Summary response should render after trace mode is selected",
      ).toBeVisible();
    }
  });
};

export const assertInspectorMemorySlotsVisible = async (page: Page) => {
  await test.step("Run inspector memory flow and assert diagnostic slots", async () => {
    await triggerMemoryAndButtonsFlow(page);
    await ui.viewMenu.actions(page).switchToMemory();
    await ui.memoryPanel.assertions(page).panelIsVisible();

    await ui.conversationLog
      .assertions(page)
      .conversationEventIsVisible("Slot inspector_memory_note set");
    await ui.conversationLog.actions(page).clickConversationEvent("Slot inspector_memory_note set");
    await ui.eventDetails.assertions(page).panelIsVisible("Slot event");
    await ui.eventDetails.assertions(page).slotOrFlowNameIsVisible("inspector_memory_note");
    await ui.eventDetails.assertions(page).slotValueIsVisible(MEMORY_NOTE);
    await ui.eventDetails.actions(page).close();

    await ui.conversationLog
      .assertions(page)
      .conversationEventIsVisible("Slot inspector_trace_mode set");
    await ui.conversationLog.actions(page).clickConversationEvent("Slot inspector_trace_mode set");
    await ui.eventDetails.assertions(page).panelIsVisible("Slot event");
    await ui.eventDetails.assertions(page).slotOrFlowNameIsVisible("inspector_trace_mode");
    await ui.eventDetails.assertions(page).slotValueIsVisible(TRACE_MODE_BUTTON);
    await ui.eventDetails.actions(page).close();
    await ui.memoryPanel.assertions(page).panelIsVisible();
  });
};
